import{c as e,Q as a,j as s,m as n}from"./chunks/framework.DOi4mjdC.js";const h=JSON.parse('{"title":"Truncate","description":"","frontmatter":{},"headers":[{"level":1,"title":"Truncate","slug":"truncate"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值","slug":"返回值"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/Reg矢量计算/类型转换/Truncate.md","filePath":"api/SIMD-API/基础API/Reg矢量计算/类型转换/Truncate.md"}'),d={name:"api/SIMD-API/基础API/Reg矢量计算/类型转换/Truncate.md"};function l(r,t,i,o,p,c){return a(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="truncate" tabindex="-1">Truncate <a class="header-anchor" href="#truncate" aria-label="Permalink to &quot;Truncate&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>x</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>x</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>将源操作数的浮点数元素截断到整数位，同时源操作数的数据类型保持不变。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T = DefaultType, RoundMode roundMode = RoundMode::CAST_NONE, MaskMergeMode mode = MaskMergeMode::ZEROING, typename S&gt;</span></span>
<span class="line"><span>__simd_callee__ inline void Truncate(S&amp; dstReg, S&amp; srcReg, MaskReg&amp; mask)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>操作数数据类型。 Ascend 950PR/Ascend 950DT，dstReg/srcReg支持的数据类型为：half、float、bfloat16_t。</td></tr><tr><td>roundMode</td><td>舍入模式，取值如下： RoundMode::CAST_NONE：默认值，该模式在转换会导致精度丢失的场景下相当于CAST_RINT，其他场景下无效果；RoundMode::CAST_RINT：该模式返回最接近参数的整数，如果有两个整数同样接近，则会返回偶数的那个；RoundMode::CAST_ROUND：round模式， 四舍五入求整；RoundMode::CAST_FLOOR：floor模式，向下取整；RoundMode::CAST_CEIL：ceil模式， 向上取整；RoundMode::CAST_TRUNC：truncation模式， 向0取整，舍弃小数位。</td></tr><tr><td>mode</td><td>选择MERGING模式或ZEROING模式。 ZEROING，mask未筛选的元素在dst中置零MERGING，当前不支持。</td></tr><tr><td>S</td><td>srcReg/dstReg 类型，例如RegTensor&lt;float&gt;，由编译器自动推导，用户不需要填写。</td></tr></tbody></table><p><strong>表 2</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>dstReg</td><td>输出</td><td>目的操作数。 类型为RegTensor。</td></tr><tr><td>srcReg</td><td>输入</td><td>源操作数。 类型为RegTensor。 源操作数的数据类型需要与目的操作数保持一致。</td></tr><tr><td>mask</td><td>输入</td><td>源操作数元素操作的有效指示，详细说明请参考MaskReg。</td></tr></tbody></table><h2 id="返回值" tabindex="-1">返回值 <a class="header-anchor" href="#返回值" aria-label="Permalink to &quot;返回值&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>非饱和模式下，输入nan，输出nan; 输入值超出输入类型的最值范围，则输出+/-inf。</li><li>饱和模式下，输入nan, 输出为0，输入值超出输入类型的最值范围时，则其被饱和为最值。</li><li>float类型只支持不饱和模式。</li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template&lt;typename T&gt;</span></span>
<span class="line"><span>__simd_vf__ inline void TruncVF(__ubuf__ T* dstAddr, __ubuf__ T* srcAddr, uint32_t count, uint32_t oneRepeatSize, uint16_t repeatTimes)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    AscendC::Reg::RegTensor&lt;T&gt; srcReg;</span></span>
<span class="line"><span>    AscendC::Reg::RegTensor&lt;T&gt; dstReg;</span></span>
<span class="line"><span>    AscendC::Reg::MaskReg mask;</span></span>
<span class="line"><span>    for (uint16_t i = 0; i &lt; repeatTimes; i++) {</span></span>
<span class="line"><span>        AscendC::Reg::LoadAlign(srcReg, srcAddr + i * oneRepeatSize);</span></span>
<span class="line"><span>        mask = AscendC::Reg::UpdateMask&lt;T&gt;(count);</span></span>
<span class="line"><span>        AscendC::Reg::Truncate&lt;T, AscendC::RoundMode::CAST_FLOOR, AscendC::Reg::MaskMergeMode::ZEROING&gt;(dstReg, srcReg, mask);</span></span>
<span class="line"><span>        AscendC::Reg::StoreAlign(dstAddr + i * oneRepeatSize, dstReg, mask);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div>`,18)])])}const g=e(d,[["render",l]]);export{h as __pageData,g as default};
